        shelf: ['#9a7448', '#e0bc84', '#3a2410'], crate: ['#b88a58', '#e8c488', '#4a2e18'], model: ['#2a1c24', '#6a5060', '#120a10'], door: ['#c8641e', '#f0a050', '#5a2a0c'],
